function renderBrandAsset(el,path,fallback){if(!el)return;const url=assetUrl(path)||'./brand-logo-blue.jpg';el.textContent='';el.style.backgroundImage=`url("${url}")`;el.classList.add('image-mark');el.classList.toggle('default-logo-mark',!path)}
function renderCompany(){const c=appState.company||{};const name=c.name||'Kantor Rio.Els_AI';try{localStorage.setItem('officeBranding',JSON.stringify({name,logo_path:c.logo_path||'',wallpaper_path:c.wallpaper_path||''}))}catch{}applyLoginBranding(c);document.title=name;['homeCompanyName','introCompanyName'].forEach(id=>{if($(id))$(id).textContent=name});$('sideCompanyName').textContent=name.replace(/^Kantor\s+/i,'');$('buildingCompanyName').textContent=`${name.toUpperCase()} · HEAD OFFICE`;$('loginBrandName').textContent=name.toUpperCase();$('introText').textContent=c.intro_text||'Perusahaan digital yang dikelola bersama tim AI untuk meneliti produk, memasarkan produk, melayani pelanggan, dan memantau kinerja usaha.';[...document.querySelectorAll('.brand-mark')].forEach(el=>renderBrandAsset(el,c.logo_path,(name.trim()[0]||'R').toUpperCase()));const building=document.querySelector('.building');const wallpaper=assetUrl(c.wallpaper_path);building.style.backgroundImage=wallpaper?`linear-gradient(110deg,rgba(13,24,45,.90),rgba(13,24,45,.75)),url("${wallpaper}")`:'';building.style.backgroundSize='cover';building.style.backgroundPosition='center';$('companyNameInput').value=c.name||'';$('companyIntroInput').value=c.intro_text||'';document.querySelectorAll('[data-platform-label]').forEach(input=>input.value=(c.platform_labels||{})[input.dataset.platformLabel]||defaultPlatformLabels[input.dataset.platformLabel]||'')}
const fmt = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(n || 0));
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
