const iconFor = (dept='') => ({Penjualan:'✦',Keuangan:'▤',Gudang:'▣',HRD:'♙','Riset Produk':'⌕','Riset Emas':'◈','Riset Saham':'▥',Editor:'✎','Layanan Pelanggan':'✉',Administrasi:'✧'})[dept] || '✦';
const showToast = (msg) => { const t=$('toast'); t.textContent=msg; t.classList.remove('hidden'); setTimeout(()=>t.classList.add('hidden'),3600); };
function applyLoginBranding(company=appState.company||{}) {
  let saved={};try{saved=JSON.parse(localStorage.getItem('officeBranding')||'{}')}catch{}
  const brand={...saved,...company};const name=brand.name||'Kantor Rio.Els_AI';const logo=assetUrl(brand.logo_path)||'./brand-logo-blue.jpg';
  const mark=$('loginLogo');if(mark){mark.textContent='';mark.style.backgroundImage=`url(\"${logo}\")`;mark.classList.add('image-mark')}
  const label=$('loginBrandName');if(label)label.textContent=name.toUpperCase();
  const art=document.querySelector('.login-art');if(art){const wallpaper=assetUrl(brand.wallpaper_path);art.style.backgroundImage=wallpaper?`linear-gradient(#07142755,#07142755),url(\"${wallpaper}\")`:'radial-gradient(ellipse at 75% 25%,#355b71 0,transparent 38%),linear-gradient(140deg,#121b30,#142b3b)';art.style.backgroundSize='cover';art.style.backgroundPosition='center'}
}
function showLogin(message='') { $('loginScreen').classList.remove('hidden'); $('app').classList.add('hidden'); $('passwordRecoveryForm').classList.add('hidden'); $('loginForm').classList.remove('hidden'); applyLoginBranding(); if(message) $('loginNotice').textContent=message; }
function showApp() { $('loginScreen').classList.add('hidden'); $('app').classList.remove('hidden'); $('sideEmail').textContent=appState.user?.email || 'Owner'; const badge=document.querySelector('.pill.owner');if(badge)badge.textContent=appState.userRole==='owner'?'CEO · Owner':'Manager · Full access'; }
function applyRoleAccess(){const panel=$('memberAccessPanel');if(panel)panel.classList.toggle('hidden',appState.userRole!=='owner')}

async function requestLogin(e) {
  e.preventDefault(); const email=$('email').value.trim(); const password=$('password').value; const btn=$('loginBtn'); btn.disabled=true; btn.textContent='Memeriksa…';
  const { error } = await supabase.auth.signInWithPassword({ email, password });
  btn.disabled=false; btn.textContent='Masuk';
  if(error){const message=(error.message||'').toLowerCase();$('loginNotice').textContent=message.includes('invalid login credentials')?'Email atau kata sandi salah. Jika belum pernah membuat kata sandi, gunakan “Lupa / atur kata sandi”.':message.includes('email not confirmed')?'Email belum dikonfirmasi. Periksa email kantor atau minta bantuan pemilik kantor.':message.includes('too many requests')?'Terlalu banyak percobaan. Tunggu sebentar sebelum mencoba kembali.':'Login gagal: '+error.message;}
}
async function requestPasswordReset() {
  const email=$('email').value.trim(); if(!email){$('loginNotice').textContent='Masukkan email kantor terlebih dahulu.'; $('email').focus(); return}
  const btn=$('resetPasswordBtn'); btn.disabled=true; btn.textContent='Mengirim tautan…';
  const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/'});
  btn.disabled=false; btn.textContent='Lupa / atur kata sandi';
  $('loginNotice').textContent=error?(error.message.toLowerCase().includes('rate limit')?'Batas email Supabase tercapai: maksimal 2 email per jam untuk seluruh proyek. Coba lagi setelah batas pulih atau aktifkan SMTP khusus.':`Tautan belum terkirim: ${error.message}`):'Tautan untuk mengatur kata sandi dikirim. Buka email satu kali, buat kata sandi, lalu login tanpa email berikutnya.';
}
async function saveNewPassword(e) {
  e.preventDefault(); const password=$('newPassword').value; if(password!==$('confirmPassword').value){$('recoveryNotice').textContent='Kedua kata sandi belum sama.';return}
  const btn=$('savePasswordBtn');btn.disabled=true;btn.textContent='Menyimpan…';const {error}=await supabase.auth.updateUser({password});btn.disabled=false;btn.textContent='Simpan kata sandi';
  if(error){$('recoveryNotice').textContent='Kata sandi belum tersimpan. Pastikan minimal 8 karakter lalu coba lagi.';return}
  await supabase.auth.signOut();passwordRecoveryActive=false;showLogin('Kata sandi tersimpan. Sekarang login dengan email dan kata sandi.');
}

async function bootSession(session) {
  if (passwordRecoveryActive) return;
  if (!session?.user) { appState.user=null; showLogin(); return; }
  const {data:membership,error:memberError}=await supabase.from('company_members').select('company_id,role').eq('user_id',session.user.id).eq('active',true).in('role',['owner','manager']).limit(1).maybeSingle();
  if(memberError||!membership){await supabase.auth.signOut();showLogin('Email ini belum mendapat akses aktif ke kantor. Minta CEO mengundang atau mengaktifkan kembali aksesnya.');return}
  appState.user=session.user; appState.userRole=membership.role; showApp(); applyRoleAccess();
  appState.companyId=membership.company_id;
  await refreshData();
}

async function refreshData() {
  if (!appState.companyId) return;
  const c=appState.companyId;
  const [company,emps,sales,products,channels,units] = await Promise.all([
    supabase.from('companies').select('name,owner_user_id,logo_path,wallpaper_path,platform_labels,platform_links,download_links,intro_text').eq('id',c).single(),
    supabase.from('ai_employees').select('id,employee_key,name,department,role_title,job_description,ai_provider,assigned_channel,floor,work_status,current_location,current_task_id,is_active,business_unit_id,avatar_path').eq('company_id',c).eq('is_active',true).order('floor').order('name'),
    supabase.from('sales_transactions').select('id,product_type,transaction_status,gross_amount,commission_amount,platform_fee,net_amount,sold_at,products(name),marketplace_accounts(provider,display_name)').eq('company_id',c).order('sold_at',{ascending:false}).limit(1000),
    supabase.from('products').select('id,name,product_type,status,source_url,created_at').eq('company_id',c).order('created_at',{ascending:false}).limit(200),
    supabase.from('marketplace_accounts').select('id,provider,display_name,connection_status,last_sync_at,last_error').eq('company_id',c).order('created_at'),
    supabase.from('business_units').select('id,code,name,unit_type').eq('company_id',c).eq('is_active',true)
  ]);
  if (emps.error) showToast('Data kantor belum bisa dimuat: '+emps.error.message);
  appState.company=company.data||{}; appState.employees=emps.data||[]; appState.sales=sales.data||[]; appState.products=products.data||[]; appState.channels=channels.data||[]; appState.units=units.data||[];
  if(appState.userRole==='owner'){const members=await supabase.from('company_members').select('company_id,user_id,email,role,active,created_at').eq('company_id',c).order('created_at');appState.members=members.data||[]}else appState.members=[];
  renderCompany();
  $('connectionBadge').textContent='Terhubung ke server'; $('connectionBadge').style.color='#25775e';
  renderHome(); renderEmployees(); renderSales(); renderProducts(); renderChannels(); renderReports(); renderChatList(); renderAccessMembers();
}

