async function saveEmployeeWithDescription(ev){ev.preventDefault();const id=$('employeeId').value||null;const dept=$('empDepartment').value.trim();const unit=appState.units.find(u=>u.code===(dept==='Riset Emas'?'gold_research':dept==='Riset Saham'?'equity_research':['Penjualan','Layanan Pelanggan','Riset Produk','Editor','Gudang'].includes(dept)?'digital_commerce':'corporate'))||appState.units[0];const config={employee_key:$('empKey').value.trim().toLowerCase(),name:$('empName').value.trim(),department:dept,role_title:$('empRole').value.trim(),job_description:$('empJobDescription').value.trim(),ai_provider:$('empAiProvider').value,assigned_channel:$('empChannel').value.trim(),floor:Number($('empFloor').value),business_unit_id:unit?.id,marketplace_assignments:[]};const avatarFile=$('empAvatar').files[0];if(!config.job_description){showToast('Deskripsi kerja harus diisi.');return}if(avatarFile&&(!['image/jpeg','image/png','image/webp'].includes(avatarFile.type)||avatarFile.size>5000000)){showToast('Foto harus JPG, PNG, atau WEBP maksimal 5 MB.');return}let savedId=id;if(appState.userRole==='owner'){const {data,error}=await supabase.rpc('save_ai_employee',{p_company_id:appState.companyId,p_employee_id:id,p_config:config});if(error){showToast('Belum tersimpan: '+error.message);return}savedId=data}else{const fields={employee_key:config.employee_key,name:config.name,department:dept,role_title:config.role_title,job_description:config.job_description,ai_provider:config.ai_provider,assigned_channel:config.assigned_channel||null,floor:config.floor,business_unit_id:unit?.id,current_location:(config.assigned_channel||dept)+` · Lantai ${config.floor}`,updated_at:new Date().toISOString()};const result=id?await supabase.from('ai_employees').update(fields).eq('company_id',appState.companyId).eq('id',id).select('id').single():await supabase.from('ai_employees').insert({...fields,company_id:appState.companyId,work_status:'waiting'}).select('id').single();if(result.error){showToast('Belum tersimpan: '+result.error.message);return}savedId=result.data.id}if(appState.userRole==='owner'){const {error}=await supabase.from('ai_employees').update({job_description:config.job_description,ai_provider:config.ai_provider}).eq('company_id',appState.companyId).eq('id',savedId);if(error){showToast('Profil tersimpan, deskripsi atau tool AI belum: '+error.message);return}}if(avatarFile&&savedId){const ext=avatarFile.type==='image/png'?'png':avatarFile.type==='image/webp'?'webp':'jpg';const path=`${appState.companyId}/team/${savedId}.${ext}`;const up=await supabase.storage.from('company-brand-assets').upload(path,avatarFile,{upsert:true,contentType:avatarFile.type});if(up.error){showToast('Foto belum tersimpan: '+up.error.message);return}const upd=await supabase.from('ai_employees').update({avatar_path:path}).eq('company_id',appState.companyId).eq('id',savedId);if(upd.error){showToast('Foto terunggah tetapi belum tertaut: '+upd.error.message);return}}$('employeeModal').classList.add('hidden');showToast('Profil, deskripsi kerja, dan tool AI disimpan.');await refreshData()}
