archiveEmployee=async function(id){const e=appState.employees.find(x=>x.id===id);if(!e||!confirm(`Arsipkan ${e.name}? Riwayat tugas dan transaksi akan tetap tersimpan.`))return;if(appState.userRole==='owner'){const {error}=await supabase.rpc('archive_ai_employee',{p_company_id:appState.companyId,p_employee_id:id});if(error){showToast('Gagal mengarsipkan: '+error.message);return}}else{const {error}=await supabase.from('ai_employees').update({is_active:false,archived_at:new Date().toISOString(),work_status:'waiting',current_task_id:null,updated_at:new Date().toISOString()}).eq('company_id',appState.companyId).eq('id',id);if(error){showToast('Gagal mengarsipkan: '+error.message);return}await supabase.from('employee_marketplace_assignments').delete().eq('company_id',appState.companyId).eq('employee_id',id)}showToast(`${e.name} diarsipkan; riwayat tetap tersimpan.`);await refreshData()};
